import os
import secrets
import hashlib
import base64
import requests
import urllib.parse


class Auth0PKCEClient:
    def __init__(self, domain=None, client_id=None, redirect_uri=None):
        self.domain = domain or os.environ.get("AUTH0_DOMAIN")
        self.client_id = client_id or os.environ.get("AUTH0_CLIENT_ID")
        self.redirect_uri = redirect_uri or os.environ.get("AUTH0_REDIRECT_URI")

        if not self.domain or not self.client_id or not self.redirect_uri:
            raise ValueError("Auth0 domain, client_id, and redirect_uri are required")

        self.authorize_url = f"https://{self.domain}/authorize"
        self.token_url = f"https://{self.domain}/oauth/token"

    @staticmethod
    def generate_code_verifier(length=96):
        return secrets.token_urlsafe(length)

    @staticmethod
    def generate_code_challenge(verifier):
        digest = hashlib.sha256(verifier.encode("utf-8")).digest()
        return base64.urlsafe_b64encode(digest).decode("utf-8").rstrip("=")

    def get_authorization_url(self, code_verifier, state, scopes="openid profile email"):
        code_challenge = self.generate_code_challenge(code_verifier)
        params = {
            "client_id": self.client_id,
            "redirect_uri": self.redirect_uri,
            "response_type": "code",
            "scope": scopes,
            "code_challenge": code_challenge,
            "code_challenge_method": "S256",
            "state": state,
        }
        query_string = urllib.parse.urlencode(params)
        return f"{self.authorize_url}?{query_string}"

    def exchange_code_for_tokens(self, code, code_verifier):
        payload = {
            "grant_type": "authorization_code",
            "client_id": self.client_id,
            "code": code,
            "redirect_uri": self.redirect_uri,
            "code_verifier": code_verifier,
        }
        headers = {"Content-Type": "application/x-www-form-urlencoded"}
        response = requests.post(self.token_url, data=payload, headers=headers)
        response.raise_for_status()
        return response.json()
